  vec3 N = normalize(vNormal);
  vec3 V = normalize(vViewPosition);
  float fresnel = pow(clamp(1.0 - abs(dot(N, V)), 0.0001, 1.0), 2.1);

  float scan = smoothstep(0.42, 0.96, 0.5 + 0.5 * sin(vObjPos.y * 34.0 - uTime * (4.5 + uListening * 3.5)));
  vec3 midnight = vec3(0.015, 0.035, 0.09);
  vec3 neonBlue = vec3(0.08, 0.46, 1.0);
  vec3 piercingCyan = vec3(0.18, 0.95, 1.0);
  vec3 iceWhite = vec3(0.84, 0.98, 1.0);

  vec3 activeWire = mix(neonBlue, piercingCyan, 0.4 + uListening * 0.45 + scan * 0.35);
  activeWire = mix(activeWire, iceWhite, clamp(vGlitch * 0.55 + uSpeaking * 0.25, 0.0, 1.0));

  vec3 col = mix(midnight, activeWire, fresnel * 0.85 + scan * 0.4);
  col += piercingCyan * vGlitch * (0.85 + uSpeaking * 0.65 + uAudioLevel * 1.4);
  col *= (1.0 + uAudioLevel * 0.75);

  gl_FragColor = vec4(col, 1.0);
}

