  vec3 baseColor = vec3(0.035);
  vec3 silverBlade = vec3(0.92, 0.94, 1.0);
  vec3 listenFrost = vec3(0.32, 0.85, 1.0);
  vec3 tarnishedGold = vec3(1.0, 0.84, 0.52);

  float spec = pow(clamp(dot(reflect(-viewDir, normal), vec3(0.0, 1.0, 0.0)), 0.0001, 1.0), 28.0);
  vec3 idleColor = mix(baseColor, mix(silverBlade, tarnishedGold, 0.22), fresnel + spec);
  vec3 listeningColor = mix(baseColor, listenFrost, fresnel + spec);
  vec3 speakingColor = mix(baseColor, tarnishedGold, fresnel + spec);

  vec3 finalColor = mix(idleColor, listeningColor, uListening);
  finalColor = mix(finalColor, speakingColor, uSpeaking);

  finalColor += vec3(0.14, 0.13, 0.16) * max(vDisplacement, 0.0);
  finalColor += vec3(0.0, 0.28, 0.48) * max(vDisplacement, 0.0) * uListening;
  finalColor += vec3(0.45, 0.3, 0.08) * max(vDisplacement, 0.0) * uSpeaking;
  finalColor *= (1.0 + uAudioLevel * 0.65);

  gl_FragColor = vec4(finalColor, 1.0);
