varying vec3 vViewPosition;
varying float vSpike;
uniform float uTime;
uniform float uAudioLevel;
uniform float uListening;
uniform float uSpeaking;
vec3 thinFilm(float ndotv, float shift) {
  return 0.5 + 0.5 * cos(6.28318 * (ndotv * 1.5 + shift + vec3(0.0, 0.33, 0.67)));
}
void main() {
  vec3 N = normalize(vNormal);
  vec3 V = normalize(vViewPosition);
  float ndotv = clamp(dot(N, V), 0.0, 1.0);
  float fresnel = pow(clamp(1.0 - ndotv, 0.0001, 1.0), 3.0);
  vec3 R = reflect(-V, N);

  float keySpec = pow(clamp(dot(R, normalize(vec3(0.55, 0.78, 0.58))), 0.0001, 1.0), 42.0);
  float fillSpec = pow(clamp(dot(R, normalize(vec3(-0.72, -0.35, 0.52))), 0.0001, 1.0), 14.0);
  float rimSpec = pow(clamp(dot(R, normalize(vec3(0.0, -0.9, 0.4))), 0.0001, 1.0), 18.0);

  vec3 idleTint = vec3(0.76, 0.84, 1.0);
  vec3 listenTint = vec3(0.15, 0.92, 1.0);
  vec3 speakTint = vec3(1.0, 0.32, 0.14);
  vec3 accent = mix(idleTint, listenTint, uListening);
  accent = mix(accent, speakTint, uSpeaking);

  vec3 oilSheen = thinFilm(ndotv, vSpike * 0.9 + uTime * 0.18 + uSpeaking * 0.4);
  vec3 obsidian = vec3(0.015, 0.018, 0.025);

  vec3 col = obsidian;
  col += mix(accent, oilSheen, 0.38) * fresnel * (1.15 + vSpike * 0.7 + uAudioLevel * 0.85);
  col += vec3(1.0, 0.98, 0.96) * keySpec * (1.6 + uAudioLevel * 0.9);
  col += accent * fillSpec * (0.85 + vSpike * 0.65);
  col += mix(accent, vec3(1.0, 0.84, 0.45), uSpeaking) * rimSpec * 0.65;
  col += accent * pow(max(vSpike - 0.55, 0.0), 2.0) * (0.45 + uAudioLevel * 0.9);

  gl_FragColor = vec4(col, 1.0);
}

