  p = fract(p * 0.1031);
  p += dot(p, p.yzx + 33.33);
  return fract((p.x + p.y) * p.z);
}
float evalPrism(vec3 dir, float t, out float shardId, out float edgeAmt) {
  float cells = 3.2 + uListening * 0.6 + uSpeaking * 0.8;
  vec3 grid = dir * cells;
  vec3 cell = floor(grid);
  vec3 f = fract(grid);
  float border = min(min(min(f.x, 1.0 - f.x), min(f.y, 1.0 - f.y)), min(f.z, 1.0 - f.z));
  edgeAmt = 1.0 - smoothstep(0.0, 0.14, border);

  shardId = hash31(cell);
  float beat = sin(t * (2.6 + shardId * 3.5) + shardId * 6.28318);
  float extrude = step(0.32, shardId) * (0.08 + uSpeaking * 0.24 + uAudioLevel * 0.58) * (0.45 + 0.55 * beat);
  return extrude - edgeAmt * (0.04 + uAudioLevel * 0.06);
}
void main() {
  vec3 dir = normalize(position);
  float t = uTime * (0.8 + uSpeaking * 0.75 + uListening * 0.3);
  float sid = 0.0;
  float edgeAmt = 0.0;
  float d0 = evalPrism(dir, t, sid, edgeAmt);
  vShardId = sid;
  vEdgeGlow = edgeAmt;

  float eps = 0.03;
  vec3 tangent = normalize(abs(dir.y) < 0.95 ? cross(dir, vec3(0.0, 1.0, 0.0)) : cross(dir, vec3(1.0, 0.0, 0.0)));
  vec3 bitangent = normalize(cross(dir, tangent));
  vec3 p1 = normalize(dir + tangent * eps);
  vec3 p2 = normalize(dir + bitangent * eps);
  float dummyA = 0.0;
  float dummyB = 0.0;

  vec3 pos0 = dir * (1.0 + d0);
  vec3 pos1 = p1 * (1.0 + evalPrism(p1, t, dummyA, dummyB));
  vec3 pos2 = p2 * (1.0 + evalPrism(p2, t, dummyA, dummyB));
  vec3 nObj = normalize(cross(pos1 - pos0, pos2 - pos0));
  if (dot(nObj, dir) < 0.0) nObj = -nObj;

  vec4 mvPosition = modelViewMatrix * vec4(pos0, 1.0);
  vViewPosition = -mvPosition.xyz;
  vNormal = normalize(normalMatrix * nObj);
  gl_Position = projectionMatrix * mvPosition;
}

